//! Cargo-driven `comctl32.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is comctl32-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x7b850000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ffa9000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ffa9000000u64)),
        o => panic!("comctl32-cargo: unsupported arch {o}"),
    };

    let late_libs: &[&str] = match arch.as_str() {
        "x86" => &["engine:uuid", "engine:wine", "engine:pseh", "engine:oldnames", "engine:chkstk", "sdk/lib/delayimp/libdelayimp_rust.a"],
        "x86_64" => &["engine:uuid", "engine:wine", "engine:pseh", "engine:oldnames", "sdk/lib/delayimp/libdelayimp_rust.a"],
        "aarch64" => &["engine:uuid", "engine:wine", "engine:pseh", "engine:oldnames", "engine:chkstk", "sdk/lib/delayimp/libdelayimp_rust.a"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("comctl32-rust")
        .resource_from_rc("dll/win32/comctl32/rsrc.rc", "comctl32_res")
        .spec2def("dll/win32/comctl32/comctl32.spec", "comctl32.dll")
        .delay_import_lib("dll/win32/winmm/winmm.spec", "winmm.dll", "winmm")
        .delay_import_lib("dll/win32/uxtheme/uxtheme.spec", "uxtheme.dll", "uxtheme")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/usp10/usp10.spec", "usp10.dll", "usp10")
        .import_lib("win32ss/user/imm32/imm32.spec", "imm32.dll", "imm32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // ...and those cmake linked after the body, in the same order.
        .static_libs_after_body(late_libs)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
